/**
 * @summary Update user role (admin only)
 */
export const getUpdateUserRoleUrl = (userId: number) => {
  return `/api/admin/users/${userId}/role`;
};

export const updateUserRole = async (
  userId: number,
  updateRoleBody: UpdateRoleBody,
  options?: RequestInit,
): Promise<AdminUser> => {
  return customFetch<AdminUser>(getUpdateUserRoleUrl(userId), {
    ...options,
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(updateRoleBody),
  });
};

export const getUpdateUserRoleMutationOptions = <
  TError = ErrorType<ErrorResponse>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof updateUserRole>>,
    TError,
    { userId: number; data: BodyType<UpdateRoleBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof updateUserRole>>,
  TError,
  { userId: number; data: BodyType<UpdateRoleBody> },
  TContext
> => {
  const mutationKey = ["updateUserRole"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof updateUserRole>>,
    { userId: number; data: BodyType<UpdateRoleBody> }
  > = (props) => {
    const { userId, data } = props ?? {};

    return updateUserRole(userId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type UpdateUserRoleMutationResult = NonNullable<
  Awaited<ReturnType<typeof updateUserRole>>
>;
export type UpdateUserRoleMutationBody = BodyType<UpdateRoleBody>;
export type UpdateUserRoleMutationError = ErrorType<ErrorResponse>;

